import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"雷火丰","description":"周易折中 - 雷火丰","frontmatter":{"title":"雷火丰","description":"周易折中 - 雷火丰"},"headers":[],"relativePath":"zh/classics/zhezhong/061.md","filePath":"zh/classics/zhezhong/061.md"}'),h={name:"zh/classics/zhezhong/061.md"};function p(n,a,d,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="雷火丰" tabindex="-1">雷火丰 <a class="header-anchor" href="#雷火丰" aria-label="Permalink to “雷火丰”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈丰序卦〉：得其所归者必大，故受之以《丰》。物所归聚必成莫大，故《归妹》之后受之以《丰》也。《丰》，盛大之义。为卦震上离下，震动也，离明也。以明而动，动而能明，皆致丰之道。明足以照，动足以亨，然后能致丰大也。”</p><p>丰：亨，王假之，勿忧，宜日中。</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>丰，大也，以明而动，盛大之势也。故其占有亨道焉。然王者至此盛极当衰，则又有忧道焉。圣人以为徒忧无益，但能守常，不至于过盛，则可矣。故戒以勿忧，宜日中也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>丰为盛大，其义自亨。极天下之光大者，唯王者能至之。假，至也。天位之尊，四海之富，群生之众，王道之大极，丰之道其唯王者乎？丰之时，人民之繁庶，事物之殷盛，治之岂易周，为可忧虑。宜如日中之盛明，广照无所不及，然后无忧也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张子曰：宜日中，不宜过中也。</p></li><li><p>郭氏忠孝曰：丰者，盛大之名。盛大所以亨，然物极盛大者，忧必将至。日过中则昃，丰过盛则衰。圣人欲持满以中，故言宜日中。</p></li><li><p>项氏安世曰：丰卦皆以明为主，故下三爻皆明而无咎，上三爻皆暗，以能求明为吉，不能求为凶。此所以宜日中也。</p></li><li><p>胡氏炳文曰：丰之大有亨道焉，大则必通也，亦有忧道焉，大则可忧也。不必过于忧，如日之中，斯可矣。泰、晋、夬、家人、升皆曰“勿恤”，此曰“勿忧”，皆当极盛之时，常人所不忧而圣人所深忧。其辞曰“勿忧”，深切之辞，非谓无忧也。</p></li><li><p>何氏楷曰：丰有忧道焉，而云勿忧，盖于此有道焉，可不必忧也。其道安在？亦曰致丰之本，即保丰之道。何以致丰？离明主之，而震动将之也。宜常如日之方中，使其明无所不及，则幽隐毕照，斯可永保夫丰亨矣。</p></li></ul><p>象曰：雷电皆至，丰。君子以折狱致刑</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>取其威照并行之象。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>雷电皆至，明震并行也。二体相合，故云皆至。明动相资成丰之象，离明也，照察之象；震动也，威断之象。折狱者必照其情实，唯明克允；致刑者以威于奸恶，唯断乃成。故君子观雷电明动之象，以折狱致刑也。噬嗑言先王饬法，丰言君子折狱，以明在上而丽于威震，王者之事故为制刑立法；以明在下而丽于威震，君子之用故为折狱致刑。旅明在上而云君子者，旅取慎用刑与不留狱，君子皆当然也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰 ：断决狱讼，须得虚实之情；致用刑罚，必得轻重之中。若动而不明，则淫滥斯及。故君子象于此卦而折狱致刑。</p></li><li><p>苏氏轼曰 ：传曰为刑罚威狱，以类天之震曜。故易至于雷电相遇，则必及刑狱，取其明以动也。至于离与艮相遇，曰“无折狱无留狱”，取其明以止也。</p></li><li><p>朱氏震曰 ：电明照也，所以折狱；雷威怒也，所以致刑。</p></li><li><p>朱子语类 ：问雷电噬嗑与雷电丰亦同，曰噬嗑明在上，是明得事理，先立这法，在此未有犯威人，留待异时之用，故云“明罚饬法”。丰威在上，明在下，是用这法时，须是明见下情曲折，方得，不然威动于上，必有过错也，故云“折狱致刑”。</p></li></ul><p>彖曰：丰，大也；明以动，故丰</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>（以卦德、卦名义释）</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>丰者，盛大之义。离明而震动，明动相资而成丰大也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>杨氏简曰 ：以明而动，故丰，故亨。以昏而动，则反是矣。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>明以动，故丰。亦非正释名义，乃推明其所以致丰之故，以起释辞之端。与壮、萃同。以字与而字不同，而字有两意，以字只是一意，重在首字。如“以刚而动”所以致壮，可见处壮者之必贞也；“以顺而说”所以致聚，可见处萃者之必顺也；“以明而动”所以致丰，可见处丰者之必明也。卦爻之义皆欲其明而防其昏，故传先发此义，以示玩辞之要。</p><p>王假之，尚大也；勿忧，宜日中，宜照天下也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>释卦辞</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>王者有四海之广、兆民之众，极天下之大也。故丰大之道，唯王者能致之。所有既大，其保之、治之之道亦当大也。故王者之所尚，至大也。所有既广、所治既众，当忧虑其不能周及，宜如日中之盛明，普照天下无所不至，则可勿忧矣。如是然后能保其丰大。保有丰大，岂小才小知之所能也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li>吴氏曰慎曰 ：所以宜日中者，恐日中则昃也。照天下，日中时昃，日中后。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>尚大谓王者至此所尚者大也。志意广大，则不能谨小虑微，而明有所不照，即昏之徴而衰之兆也。故言宜日中者，谓能常明不昏，则能常中不昃。</p><p>日中则昃，月盈则食；天地盈虚，与时消息，而况于人乎？况于鬼神乎？</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>（此又阐明卦辞外意，言不可过中也）</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>既言丰盛之至，复言其难常以为诫也。日中盛极则当昃昳，月既盈满则有亏缺。天地之盈虚尚与时消息，况人与鬼神乎？盈虚谓盛衰，消息谓进退。天地之运亦随时进退也。鬼神谓造化之迹于万物，盛衰可见其消息也。于丰盛之时而为此诫，欲其守中不至过盛，处丰之道岂易也哉。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰 ：先陈天地，后言人、鬼神者，欲以轻譬重，亦先尊后卑也。日月先天地者，承上“宜日中之文”，遂言其昃食，因举日月以对，然后并陈天地。作文之体也。</p></li><li><p>朱子语类云 ：丰卦彖许多言语，其实只在“日中则昃，月盈则食，天地盈虚，与时消息”数语上。这盛得极，常须谨谨保守得日中时候，方得。不然，便是偃仆倾壊了。 问 ：鬼神者，造化之迹。然天地盈虚即是造化之迹矣，而复言鬼神何耶？ 曰：天地举全体而言，鬼神指其功用之迹，似有人所为者。</p></li><li><p>问 ：鬼神者，造化之迹。然天地盈虚即是造化之迹矣，而复言鬼神何耶？ 曰：天地举全体而言，鬼神指其功用之迹，似有人所为者。</p></li><li><p>毛氏璞曰 ：丰大也，亦盈也。惟有道者明德若不足，未尝中故不昃，未尝盈故不食。日新则为大，反是则为盈。知日中之宜，则知日昃之可戒。</p></li><li><p>林氏希元曰 ：卦辞“勿忧，宜日中”，所以然处未之及此方言之，以补卦辞之所未及。故曰“发明卦辞外意”，言卦外之意也。虽曰辞外之意，然实有此意，但辞不及耳。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>林氏之说得之。朱子释彖辞亦曰：盛极当衰也。</p><p>初九：遇其配主，虽旬无咎，往有尚。</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>配主，谓四。旬，均也，谓皆阳也。当丰之时，明动相资，故初九之遇九四，虽皆阳刚，而其占如此也。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>雷电皆至，成丰之象。明动相资，致丰之道。非明无以照，非动无以行，相须犹形影相资，犹表里。初九明之初，九四动之初，宜相须以成其用。故虽旬而相应，位则相应用则相资。故初谓四为配主，已所配也。配虽匹称，然就之者也，如配天以配君子。故初于四云“配”，四于初云“夷”也。虽旬无咎，旬均也。天下之相应者，常非均敌，如阴之应阳，柔之从刚，下之附上。敌则安肯相从？唯丰之初四，其用则相资，其应则相成，故虽均是阳刚，相从而无过咎也。盖非明则动无所之，非动则明无所用，相资而成用。同舟则胡越一心，共难则仇怨恊力，事势使然也。往而相从，则能成其丰，故云有尚，有可嘉尚也。在它卦则不相下而离隙矣。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏瑗曰：旬者，十日也，谓数之盈满也。言初与四其徳相符，虽居盈满盛大之时，可以无咎。以此而往，则行有所尚也。</p></li><li><p>苏氏轼曰：凡人知生于忧患而愚生于安佚。丰之患常在于暗，故爻皆以明暗为吉凶也。初九、六二、九三三者皆离也，而有明徳者也。九四、六五、上六则所谓丰而暗者也。离，火也，日也，以下升上，其性也以明发暗，其徳也。故三离皆上适于震，初九适四，其配之所在也，故曰配主。</p></li><li><p>项氏安世曰：初以四为配，四以初为夷，上下异辞也。自下并上曰配。</p></li><li><p>胡氏炳文曰：初不言丰，初未至丰也。五亦不言丰者，阴虚欢然，方赖在下之助，不知有其丰也。凡卦爻取刚柔相应，丰则取明动相资。初之刚与四之刚同徳而相遇，虽两阳之势均敌，往而从之，非特无咎，且有尚矣。或曰十日为旬。</p></li><li><p>来氏知徳曰：因“宜日中”句，爻辞皆以日言。文王象丰以一日象之，故曰“勿忧，宜日中”。周公象丰以十日象之，故曰“虽旬无咎”。十日为旬，言初之丰以一月论已，一旬也正丰之时也。</p></li></ul><p>象曰：虽旬无咎，过旬灾也</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>戒占者不可求胜其配，亦爻辞外意。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>圣人因时而处宜，随事而顺理。夫势均则不相下者，常理也。然有虽敌而相资者，则相求也，初四是也。所以虽旬而无咎也。与人同而力均者，在乎降已以相求，协力以从事。若怀先已之私，有加上之意，则患当至矣。故曰过旬灾也。均而先已是过旬也，一求胜则不能同矣。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>刘氏牧曰 ：旬数之极也，犹日之中也。言无咎者，谓初未至中，犹可进也；若进而过中，则灾，故象称“过旬灾”也。爻辞不言丰者，谓初未至丰也。</p></li><li><p>胡氏瑗曰 ：言虽居丰盈之时，可以无咎；若过于盈满，则必有倾覆之灾也。</p></li><li><p>俞氏琰曰 ：爻辞云“虽旬无咎”，爻传云“过旬灾”，则戒其不可过也。盖与彖传“天地日月”说同。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>过旬灾即日中则昃，月盈则食之意也。经意谓同德相济，虽当盈满之时可以无咎，况初居丰之始，未及日中乎？传意则谓正宜及今而图之，耳稍过于中，便将有灾矣。其义相备也。</p><p>六二：丰其蔀，日中见斗，往得疑疾，有孚发若，吉。</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>六二居丰之时，为离之主，至明者也。而上应六五之柔暗，故为丰蔀见斗之象。蔀，障蔽也，大其障蔽，故日中而昏也。往而从之，则昏暗之主必反见疑。唯在积其诚意以感发之，则吉。戒占者宜如是也。虚中有孚之象。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>明动相资，乃能成丰。二为明之主，又得中正，可谓明者也。而五在正应之地，阴柔不正，非能动者。二五虽皆阴，而在明动相资之时，居相应之地，五才不足，既其应之才不足资，则独明不能成丰。既不能成丰，则丧其明功，故为丰其蔀，日中见斗。二至明之才，以所应不足与而不能成其丰，丧其明功，无明功则为昏暗，故云见斗。斗昏见者也。蔀，周匝之义，用障蔽之物掩晦于明者也。斗属阴而主运平，象五以阴柔而当君位，日中盛明之时乃见斗，犹丰大之时乃遇柔弱之主。斗以昏见，言见斗，则是明丧而暗矣。二虽至明中正之才，所遇乃柔暗不正之君，既不能下求于己，若往求之，则反得疑猜忌疾。暗主如是也。然则如之何而可？夫君子之事上也，不得其心，则尽其至诚以感发其志意而已。苟诚意能动，则虽昏蒙可开也，虽柔弱可辅也，虽不正可正也。古人之事庸君常主而克行其道者，已之诚意上逹而君见信之笃耳。管仲之相桓公，孔明之辅后主是也。若能以诚信发其志意，则得行其道，乃为吉也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>服氏䖍曰：日中而昏也。</p></li><li><p>张子曰：凡言往者，皆进而之上也。初进而上，则遇阳而有尚；二既以阴居阴，又所应亦阴，故往増疑疾。</p></li><li><p>郭氏雍曰：六二为离明之中，而有丰蔀之暗者，以阴居阴上，非正应，所以有从暗之象也。天下之理，明则无疑，暗则疑。六二用明投暗，往得疑疾，乃其宜也。然任其中正，有孚而发，则动无不吉。</p></li><li><p>徐氏㡬曰：卦言“宜日中”，以下体言之，则二为中；以一卦言之，则三四为中。故二三四皆言日中。刚生明，故初应四，则为往有尚；柔生暗，故二应五，为往得疑疾也。</p></li></ul><p>象曰：有孚发若，信以发志也</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>有孚发若，谓以已之孚信感发上之心志也。苟能发，则其吉可知，虽柔暗有可发之道也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>赵氏汝梅曰 ：疾得于境之疑，孚发于志之信。</p></li><li><p>王氏申子曰 ：二虚中故有孚，五亦虚中故可发言，以诚相感也。</p></li></ul><p>九三：丰其沛，日中见沬，折其右肱，无咎。</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>沛，一作斾，谓幡幔也。其蔽甚于蔀矣。沬，小星也。三处明极而应上六，虽不可用，而非咎也。故其象占如此。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>沛字，古本有作斾字者。王弼以为幡幔，则是斾也。幡幔围蔽于内者，丰其沛，其暗更甚于蔀也。三明体而反暗于四者，所应阴暗故也。三居明体之上，阳刚得正，本能明者也。丰之道必明动相资而成，三应于上六，上阴柔又无位而处震之终，既终则止矣，不能动者也。它卦至终则极，震至终则止矣。三无上之应，则不能成丰。沫星之微小无名数者，见沫暗之甚也。丰之时而遇上六，日中而见沫者也。右肱人之所用，乃折矣，其无能为可知。贤智之才遇明君，则能有为于天下；上无可赖之主，则不能有为，如人之折其右肱也。人之为有所失，则有所归咎，曰“由是故致是”。若欲动而无右肱，欲为而上无所赖，则不能而已，更复何言，无所归咎也。</p><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><ul><li>九三之蔽又甚于二四者。爻取日中为昏义，二三四在一卦之中，而九三又在三爻之中也。且二应五，为柔中之主；四应初，为同徳之助；三所应者，乃过中处极之阴，其蔽安得不甚哉？上六以其昏昏，使人昏昏。故九三虽以刚明之才为之股肱，而不免于毁折。然于义为无咎者，守其刚正以事上，反己无怍而众无尤也。</li></ul><p>九三之蔽又甚于二四者。爻取日中为昏义，二三四在一卦之中，而九三又在三爻之中也。且二应五，为柔中之主；四应初，为同徳之助；三所应者，乃过中处极之阴，其蔽安得不甚哉？上六以其昏昏，使人昏昏。故九三虽以刚明之才为之股肱，而不免于毁折。然于义为无咎者，守其刚正以事上，反己无怍而众无尤也。</p><ul><li>易中所取者虽虚象，然必天地闲有此实事，非凭虚造设也。日中见斗，甚而至于见沬，所取喻者固谓至昏伏于至明之中。然以实象求之，则如太阳食时是也。食限多则大星见，食限甚则小星亦见矣。所以然者，阴气蔽障之故。故所谓“丰其蔀”，“丰其沛”者，乃蔽日之物，非蔽人之物也。且此义亦与彖传“日中则昃，月盈则食”相发。</li></ul><p>易中所取者虽虚象，然必天地闲有此实事，非凭虚造设也。日中见斗，甚而至于见沬，所取喻者固谓至昏伏于至明之中。然以实象求之，则如太阳食时是也。食限多则大星见，食限甚则小星亦见矣。所以然者，阴气蔽障之故。故所谓“丰其蔀”，“丰其沛”者，乃蔽日之物，非蔽人之物也。且此义亦与彖传“日中则昃，月盈则食”相发。</p><p>象曰：丰其沛，不可大事也；折其右肱，终不可用也</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>三应于上，上应而无位，阴柔无势力而处既终，其可共济大事乎？既无所赖，如右肱之折，终不可用矣。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>潘氏士藻曰 ：六二虽当丰蔀之时，然五得位得中，犹可以大事，故六二发若之孚可施也。九三所应上六，无可发之明矣，不可用而不用，保身之哲也。</li></ul><p>九四：丰其蔀，日中见斗，遇其夷主，吉。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>象与六二同。夷，等夷也，谓初九也。其占为当丰而遇暗主，下就同徳则吉也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>四虽阳刚，为动之主，又得大臣之位，然以不中正，遇阴暗柔弱之主，岂能致丰大也？故为丰其蔀。蔀，周围掩蔽之物，周围则不大，掩蔽则不明。日中见斗，当盛明之时反昏暗也。夷主，其等夷也，相应故谓之主。初四皆阳而居初，是其同徳，又居相应之地，故为夷主。居大臣之位，而得在下之贤同徳相辅，其助岂小也哉？故吉也。如四之才，得在下之贤为之助，则能致丰大乎？曰：在下者上有当位为之与，在上者下有贤才为之助，岂无益乎？故吉也。然而致天下之丰，有君而后能也。五阴柔居尊，而震体无虚中巽顺下贤之象，下虽多贤，亦将何为？盖非阳刚中正，不能致天下之丰也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：据初适四，则以四为主，故曰“遇其配主”。自四之初，则以初为主，故曰“遇其夷主”也。</p></li><li><p>张子曰：近比于五，故亦云“见斗”。正应亦阳，故云“夷主”。</p></li><li><p>郭氏雍曰：二之丰蔀见斗，以重阴而非正应也，而有孚发若吉者，中正也。四之丰蔀见斗，非中正也，而遇其夷主吉，者应初而有遇也。二爻之义相类，故其辞同而皆终之以吉。有为之时，明动必相济然后有成，故初谓四为配主，四谓初为夷主。迭称主者，明动相须，莫适为主。惟明者知求动以为主，动者知求明以为主，故也。</p></li><li><p>郑氏汝谐曰：初视四为配，以下偶上也；四视初为夷，降上就下也。</p></li></ul><p>象曰：丰其蔀，位不当也；日中见斗，幽不明也；遇其夷主，吉行也</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>位不当，谓以不中正居高位，所以暗而不能致丰。日中见斗，幽不明也，谓幽暗不能光明。君阴柔而臣不中正，故也。遇其夷主吉行也，阳刚相遇，吉之行也。下就于初，故云行，下求则为吉也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>项氏安世曰 ：六二指六五为蔀为斗，故往则入于暗而得疑；九四之蔀与斗皆自指也，故行则遇明而得吉。</p></li><li><p>吴氏澄曰 ：丰蔀见斗，六二爻辞已备，象传不释而独九四致其详者，盖二象由九四而成，四为蔀，故二见斗；二爻之象同而所重在四也。</p></li></ul><p>六五：来章有庆誉，吉。</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>质虽柔暗，若能来致天下之明，则有庆誉而吉矣。盖因其柔暗而设此以开之，占者能如是，则如其占矣。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>五以阴柔之才为丰之主，固不能成其丰大。若能来致在下章美之才而用之，则有福庆，复得美誉，所谓吉也。六二文明中正，章美之才也。为五者诚能致之，在位而委任之，可以致丰大之庆，名誉之美，故吉也。章美之才主二而言，然初与三四皆阳刚之才，五能用贤，则彚征矣。二虽阴，有文明中正之徳，大贤之在下者也。五与二虽非阴阳正应，在明动相资之时，有相为用之义。五若能来章，则有庆誉而吉也。然六五无虚已下贤之义，圣人设此义以为教耳。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>冯氏当可曰：六二言“往”，六五言“来”，往来交合，章明之象。</p></li><li><p>项氏安世曰：六二以五为蔀，在上而暗也；六五以二为章，在下而明也。</p></li><li><p>陈氏曰：五阴暗则往而疑，二文明则来而章。章者，离体文明之象。</p></li><li><p>胡氏炳文曰：三爻称“日中”，皆有所蔽；六五不称“日中”，盖宜日中无蔽也。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>五，君位也。彖辞所谓“王假之者”，即此位。则五乃卦主也。卦义所重在明以照天下，六五虽非明体，然下应六二为文明之主，而五有柔中之徳，能资其章明以自助，则卦义所谓“勿忧，宜日中”者，实与此爻义合。</p><p>象曰：六五之吉，有庆也</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>其所谓吉者，可以有庆福及于天下也。人君虽柔暗，若能用贤才，则可以为天下之福，唯患不能耳。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li>何氏楷曰 ：人君以天下常丰为庆，庆以天下故，吉言庆则誉在其中矣。</li></ul><p>上六：丰其屋，蔀其家，窥其戸，阒其无人，三岁不觌，凶。</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>以阴柔居丰极，处动终，明极而反暗者也。故为丰大其屋而反以自蔽之象。无人不觌，亦言障蔽之深，其凶甚矣。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>六以阴柔之质而居丰之极，处动之终，其满假躁动甚矣。处丰大之时，宜乎谦屈而处，极高致丰大之功，在乎刚健而体阴柔。当丰大之任，在乎得时而不当位，如上六者，处无一当，其凶可知。丰其屋，处太高也；蔀其家，居不明也。以阴柔居丰大而在无位之地，乃高亢昏暗，自绝于人，人谁与之？故窥其戸，阒其无人也。至于三岁之久而不知变，其凶宜矣。不觌，谓尚不见人，盖不变也。六居卦终，有变之义而不能迁，是其才不能也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>龚氏焕曰：丰卦与明夷相似，唯变九四一爻。丰其蔀蔽，皆六五、上六二阴所为。二丰其蔀，以五为应也；三丰其沛，以上为应也；四丰其蔀，以承五也。然五虽柔暗，以其得中，故有来章之吉；上居丰极，始则蔽人之明，终以自蔽，与明夷上六相似。</p></li><li><p>何氏楷曰：处丰之极，亢然自高，丰大其居。以明得意，方且深居简出，距人于千里之外，岂知凶将及矣？能无惧乎？</p></li></ul><h3 id="总论" tabindex="-1">总论 <a class="header-anchor" href="#总论" aria-label="Permalink to “总论”">​</a></h3><ul><li>熊氐良辅曰：丰六爻以不应为善。初四皆阳，初曰“遇其配主”，四曰“遇其夷主”；二五皆阴，二曰“有孚发若吉”，五曰“来章有庆誉吉”。三与上为正应，三不免于折肱，而上则甚凶。当丰大之时，以同徳相辅为善，不取阴阳之应也。</li></ul><p>象曰：丰其屋，天际翔也；窥其戸，阒其无人，自藏也</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>藏谓障蔽。</p><h3 id="程传-17" tabindex="-1">程传 <a class="header-anchor" href="#程传-17" aria-label="Permalink to “程传”">​</a></h3><p>六处丰大之极，在上而自高，若飞翔于天际，谓其高大之甚。窥其户而无人者，虽居丰大之极而实无位之地，人以其昏暗自高大，故皆弃绝之，自藏避而弗与亲也。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>石氏介曰 ：始显大终自藏，皆圣人戒其过盛。子云曰：“炎炎者灭，隆隆者绝。”观雷观火，为盈为实，天收其声，地藏其热。高明之家，鬼瞰其室，正合此义。</p></li><li><p>张子曰 ：丰屋蔀家，自蔽之甚，穷大而失居者也。处上之极不交于下，而居动之末，故曰天际翔也。</p></li><li><p>朱子语类云 ：丰其屋，天际翔也，似说如翚斯飞様，言其屋高大到于天际，却只是自蔽障得阔。</p></li></ul>',129)])])}const m=l(h,[["render",p]]);export{b as __pageData,m as default};
